      "research": {
        "name_origin": "“乳钉纹簋”的名称由器类、纹饰、结构或器主线索组成。簋是盛放黍稷等熟食的食器，后来成为与鼎配合使用的礼器；“乳钉纹”指器表整齐排列的半球状突起，名称来自纹饰的颗粒形态",
        "history": "“簋”是青铜时代盛放黍、稷等熟食的礼器，乳钉纹则是器表以突起乳钉组成的装饰名称。宝鸡一带商末周初墓葬、窖藏中常见鼎簋成组出现，说明它不只是日用盛器，更嵌在祭祀、宴飨与身份秩序之中。",
        "form": "这类器物通常有圆腹、双耳与圈足，口沿和腹部的比例决定了器物的庄重感；乳钉纹以规整突起形成颗粒状节奏，既填充器表，也强化了光线在青铜锈色上的起伏。",
        "decoration": "本组照片应先看口沿、耳部与圈足，再看乳钉纹的排列是否连续、是否与雷纹或兽面纹共存。名称中的“乳钉纹”是纹饰识别，不是铭文释读。",
        "inscription": "本组没有稳定可核对的铭文释文。器名、族名或纪年若出现在名称中，只表示展签识别线索，不等于已经完成逐字释读。",
        "significance": "乳钉纹簋适合用来观察商周礼器如何把容量、组合关系与纹饰秩序合在一起：器形承担礼食功能，纹饰则把等级与仪式感固定在器表。",
        "viewing": "先看正面判断腹部和双耳，再用侧面确认圈足；局部图重点放在乳钉纹的起止、足部转折和铸造痕迹。",
        "evidence": "名称依据后置介绍牌与照片顺序校正；展签线索：时代为“商代”，来源为“1973年扶风县法门镇美阳村出土”，收藏单位为“扶风县博物馆”。"
      }
