        "name_origin": "“重父乙卣”的名称由器类、纹饰、结构或器主线索组成。卣是有盖、有提梁或环钮的盛酒器，器名最后的“卣”说明器类；名称中的人名、族氏或作器者称谓，是器物专名的来源；它们可能与铭文中的自称、受命者或家族记忆有关",
        "history": "“重父乙卣”的卡片名称取自后置介绍牌，而不是把时代名称当作文物名称。它被放入宝鸡青铜文明的现场序列中，作为观察器形、纹饰、用途与收藏语境的独立入口。",
        "form": "本组照片保留重父乙卣的正面、侧面、背面或局部视角；形制判断以器身轮廓、口沿、足部、耳部和连接结构为基础，暂不把模糊背景文字当作器物信息。",
        "decoration": "重父乙卣的纹饰和可能的刻划应以局部照片为准。若展签出现铭文栏，名称只作为检索线索；完整释文仍应回看清晰拓片、现场展签或正式图录。",
        "inscription": "本组没有稳定可核对的铭文释文。器名、族名或纪年若出现在名称中，只表示展签识别线索，不等于已经完成逐字释读。",
        "significance": "这件器物的价值不只在于“年代久远”，还在于它如何把材料、工艺、使用场景和社会关系留在可观察的形体上。",
        "viewing": "先看主图建立整体轮廓，再按正面—侧面—背面—局部的顺序观察；如果同名器物合并在一张卡片中，可用照片编号区分不同现场单元。",
        "evidence": "名称依据后置介绍牌与照片顺序校正；展签线索：时代为“商末周初”，来源为“2012年渭滨区石鼓山墓地三号墓出士”，收藏单位为“宝鸡市渭滨区博物馆”。"
