        "significance": "把它们单独列出，可以避免把陶瓷、建筑构件和青铜礼器混在“其他”里，也能看到宝鸡地区物质文化从礼制重器向日常技术与空间建造的延伸。",
        "viewing": "先看材料和结构，再看表面工艺；小型陶瓷或构件优先使用裁切图，避免被展柜和背景比例误导。",
