        "name_origin": "“何尊”的名称由器类、纹饰、结构或器主线索组成。尊是盛酒礼器，器名最后的“尊”说明用途与器类；名称中的人名、族氏或作器者称谓，是器物专名的来源；它们可能与铭文中的自称、受命者或家族记忆有关",
        "history": "“何尊”的卡片名称取自后置介绍牌，而不是把时代名称当作文物名称。它被放入宝鸡青铜文明的现场序列中，作为观察器形、纹饰、用途与收藏语境的独立入口。",
        "form": "本组照片保留何尊的正面、侧面、背面或局部视角；形制判断以器身轮廓、口沿、足部、耳部和连接结构为基础，暂不把模糊背景文字当作器物信息。",
        "decoration": "何尊的纹饰和可能的刻划应以局部照片为准。若展签出现铭文栏，名称只作为检索线索；完整释文仍应回看清晰拓片、现场展签或正式图录。",
        "inscription": "现场介绍牌出现了“铭文释文/铭文大意”等栏位；本页将其作为铭文线索保留，未把 OCR 误读直接改写成定本。",
        "significance": "这件器物的价值不只在于“年代久远”，还在于它如何把材料、工艺、使用场景和社会关系留在可观察的形体上。",
        "viewing": "先看主图建立整体轮廓，再按正面—侧面—背面—局部的顺序观察；如果同名器物合并在一张卡片中，可用照片编号区分不同现场单元。",
