      "research": {
        "name_origin": "“目雷纹带盖双耳簋”的名称由器类、纹饰、结构或器主线索组成。簋是盛放黍稷等熟食的食器，后来成为与鼎配合使用的礼器；“目雷纹”以目形单元和回旋雷纹组成连续带饰，名称强调纹样的视觉单元；“双耳”说明器身两侧设耳，需结合口沿与圈足一起判断器类",
        "history": "“目雷纹带盖双耳簋”属于簋类食器系统，名称中的纹饰、耳数或器主标识来自展签。簋与鼎常以组合方式出现，观察它时应同时想到它在祭祀、宴飨和墓葬随葬中的配套关系。",
        "form": "簋通常以圆腹、双耳和圈足为基本结构，带盖、方座、四耳或双环耳会改变器物的体量与礼仪等级感。照片要把耳、盖钮、腹部纹带和圈足看作一个整体，而不是只看正面图案。",
        "decoration": "目雷纹带盖双耳簋的纹饰名称说明了视觉重点；器主名或族名则可能与铭文有关，但仅凭现场照片不能把 OCR 片段当作完整释文。出现“铭文释文”的展签，优先回看局部照片与正式拓本。",
        "inscription": "本组没有稳定可核对的铭文释文。器名、族名或纪年若出现在名称中，只表示展签识别线索，不等于已经完成逐字释读。",
        "significance": "簋把“食器”与“礼器”两个层面叠在一起：它一方面有明确的容纳功能，另一方面通过成组配置、器主铭记和纹饰秩序进入周代礼制。",
        "viewing": "先看圈足和耳部确认器类，再看盖与腹部是否同铭、纹带是否连续；成组照片合并后，可用缩略图对比不同角度的同一器物。",
        "evidence": "名称依据后置介绍牌与照片顺序校正；展签线索：时代为“西周”，来源为“1980年渭滨区竹园沟国墓地十三号墓出土”，收藏单位为“中国青铜器博物院”。"
      }
