      "research": {
        "name_origin": "“人面盾饰”的名称由器类、纹饰、结构或器主线索组成。名称指向兵器或车马器的功能部件，器形、受力面与装配位置比朝代标签更能说明其用途",
        "history": "“人面盾饰”属于兵器或车马器。宝鸡周秦墓葬中，戈、剑、弩机、当卢、轭饰等往往与军事技术、车战和贵族身份同时出现，器物的功能不能与墓葬组合关系分开理解。",
        "form": "兵器要看刃部、援、内、胡、穿、茎、格等结构；车马器则要看连接、受力和装饰位置。照片中的局部图可以帮助判断它是实用部件、仪仗装饰还是兼具礼仪意义的象征物。",
        "decoration": "人面盾饰的名称主要来自器形、用途或纹饰；如果出现“铭文释文”栏，铭文往往提供器主、纪年、工官或使用背景。没有稳定释读之前，本页只保留展签可确认的主题。",
        "inscription": "本组没有稳定可核对的铭文释文。器名、族名或纪年若出现在名称中，只表示展签识别线索，不等于已经完成逐字释读。",
        "significance": "兵器与车马器显示青铜技术并不只服务于祭祀礼器，也参与军事组织、交通和身份展演；它们是理解周秦社会结构的另一条入口。",
        "viewing": "先找出受力或使用部位，再看纹饰和铸造细节；剑看茎、格、首与刃，戈看援、内和穿，车马器看连接面与装饰面。",
        "evidence": "名称依据后置介绍牌与照片顺序校正；展签线索：时代为“西周”，来源为“1976年岐山县贺家村砖厂四号墓出土”，收藏单位为“岐山县周原博物馆”。"
      }
