      "summary": "或方鼎：按现场顺序归档；详情页按名称、形制、纹饰与铭文线索展开。",
      "status": "名称依据后置展签校正",
      "hasObjectPhoto": true,
      "labelEvidence": "或（dong）方鼎\n代：西周\n原：1975年扶风县法门镇庄白村墓葬出土\n单位：扶风县博物馆\ngular ritual vesscl（ding)ofDong",
      "labelFacts": {},
