        "history": "“刖人守门方鼎”以鼎为器类，名称中的其余部分来自纹饰、器主、纪年或出土地线索。鼎在商周礼制中兼具炊煮、盛食与祭祀功能，宝鸡周原及其周边墓葬、窖藏所见鼎类，常被放在理解宗族、宴飨和政治秩序的核心位置。",
        "form": "鼎的基本识别点是腹、耳、足三部分；圆鼎与方鼎的口腹关系不同，分裆、附耳、带盖等变化又会改变使用方式与视觉重心。照片中可从足的数量与分布、耳的安装位置、腹部是否有扉棱来判断形制。",
        "decoration": "刖人守门方鼎的纹饰线索以展签名称为准；若名称含“兽面、云雷、涡、乳钉、夔凤”等词，它们分别提示主体纹样，而不是可以直接替代完整铭文的释读。若展签出现“铭文释文”栏，本页只把器名与可核对的铭文主题分开呈现。",
        "inscription": "本组没有稳定可核对的铭文释文。器名、族名或纪年若出现在名称中，只表示展签识别线索，不等于已经完成逐字释读。",
