      "summary": "音乐与礼乐重点：云纹编钟。按现场顺序归档，优先观察器形分区、悬挂结构与铭文位置。",
      "status": "名称依据后置展签校正",
      "hasObjectPhoto": true,
      "labelEvidence": "云纹编钟\n时代：西周\n来源：1980年渭滨区竹园沟強国墓地七号墓出\n收藏单位：中国青铜器博物院\nChimeBllwithloud pattern\nWestem Zhou\nPOXE",
      "labelFacts": {
        "period": "西周",
        "findspot": "1980年渭滨区竹园沟強国墓地七号墓出",
        "collection": "中国青铜器博物院"
      },
      "inscriptionFocus": false,
      "sourceUnits": [
        {
          "start": 3551,
          "end": 3552,
          "id": "photo-group-3551"
        }
      ],
      "unitCount": 1,
      "sequenceRanges": [
        "3551—3552"
      ],
      "sequenceLabel": "3551—3552",
      "sequenceShortLabel": "3551—3552",
      "research": {
        "name_origin": "“云纹编钟”的名称由器类、纹饰、结构或器主线索组成。“钟”“镈”与“编钟”属于击奏乐器名称，铭文和成组悬挂关系是礼乐身份的重要证据",
        "history": "“云纹编钟”属于古代礼乐系统中的声音器物。钟、镈与编钟并非脱离仪式的独奏乐器，它们的形制、数量、悬挂方式和铭文，往往与王室、诸侯、祭祀和宴飨秩序相连。",
        "form": "钟体的钲、鼓、篆、枚、舞和旋共同决定发声与悬挂；镈与钟在体量、音响和仪式位置上各有侧重，编钟则通过一组大小相次的钟形成音高序列。",
        "decoration": "音乐类器物的铭文常记录铸造缘由、受命者、赏赐或祝祷语；纹饰则不只是表面装饰，还会在钟体分区中形成稳定的节拍感。现场照片里应特别看钟面分区、枚的排列、篆部纹样与铭文所在位置。",
        "inscription": "本组没有稳定可核对的铭文释文。器名、族名或纪年若出现在名称中，只表示展签识别线索，不等于已经完成逐字释读。",
        "significance": "这些器物把“声音”变成可见的制度：铭文告诉人们谁在何种礼仪中铸钟，器形和组合则让权力、身份与秩序获得听觉形式。",
        "viewing": "先看单件钟体的区划，再看多件钟的大小递次和悬挂关系；有铭文局部时，先确认字口位置和行列，再讨论内容，不以模糊 OCR 代替释读。",
        "evidence": "名称依据后置介绍牌与照片顺序校正；展签线索：时代为“西周”，来源为“1980年渭滨区竹园沟強国墓地七号墓出”，收藏单位为“中国青铜器博物院”。"
      }
