        "inscription": "本组没有稳定可核对的铭文释文。器名、族名或纪年若出现在名称中，只表示展签识别线索，不等于已经完成逐字释读。",
        "significance": "这件器物的价值不只在于“年代久远”，还在于它如何把材料、工艺、使用场景和社会关系留在可观察的形体上。",
        "viewing": "先看主图建立整体轮廓，再按正面—侧面—背面—局部的顺序观察；如果同名器物合并在一张卡片中，可用照片编号区分不同现场单元。",
        "evidence": "名称依据后置介绍牌与照片顺序校正；展签线索：时代为“西周”，来源为“1980年渭滨区竹园沟强国墓地七号墓出土”，收藏单位为“中国青铜器博物院”。"
