        "history": "“玉琮”属于玉石、金属装饰或镜类器物。它们的体量虽小，却常与佩饰、身份、礼仪和墓葬随葬体系有关，不能因为照片中的尺寸小就把它们当作普通杂件。",
        "form": "玉佩、玉环、玉鸟、石兽面和铜镜的识别重点分别在穿孔、佩系、对称性、磨制面与背部结构；金环、铜泡等小件则要看截面、边缘和固定方式。小件照片已优先调用裁切图，原片编号仍保留在详情页。",
        "decoration": "玉琮的纹样或动物造型通常承担识别与象征双重作用；目前不把器物表面的刻划或反光直接解释成铭文，除非现场展签或正式图录给出明确释读。",
