      "sequenceShortLabel": "3649—3654",
      "research": {
        "name_origin": "“秦公钟”的名称由器类、纹饰、结构或器主线索组成。“钟”“镈”与“编钟”属于击奏乐器名称，铭文和成组悬挂关系是礼乐身份的重要证据；名称中的人名、族氏或作器者称谓，是器物专名的来源；它们可能与铭文中的自称、受命者或家族记忆有关",
        "history": "“秦公钟”属于古代礼乐系统中的声音器物。钟、镈与编钟并非脱离仪式的独奏乐器，它们的形制、数量、悬挂方式和铭文，往往与王室、诸侯、祭祀和宴飨秩序相连。",
        "form": "钟体的钲、鼓、篆、枚、舞和旋共同决定发声与悬挂；镈与钟在体量、音响和仪式位置上各有侧重，编钟则通过一组大小相次的钟形成音高序列。",
        "decoration": "音乐类器物的铭文常记录铸造缘由、受命者、赏赐或祝祷语；纹饰则不只是表面装饰，还会在钟体分区中形成稳定的节拍感。现场照片里应特别看钟面分区、枚的排列、篆部纹样与铭文所在位置。",
        "inscription": "现场介绍牌出现了“铭文释文/铭文大意”等栏位；本页将其作为铭文线索保留，未把 OCR 误读直接改写成定本。",
        "significance": "这些器物把“声音”变成可见的制度：铭文告诉人们谁在何种礼仪中铸钟，器形和组合则让权力、身份与秩序获得听觉形式。",
        "viewing": "先看单件钟体的区划，再看多件钟的大小递次和悬挂关系；有铭文局部时，先确认字口位置和行列，再讨论内容，不以模糊 OCR 代替释读。",
        "evidence": "名称依据后置介绍牌与照片顺序校正；展签线索：时代为“春秋”，来源为“1978年陈仓区太公庙村出土”，收藏单位为“中国青铜器博物院”。"
      }
