      "summary": "连珠纹扁茎剑：按现场顺序归档；详情页按名称、形制、纹饰与铭文线索展开。",
      "status": "名称依据后置展签校正",
      "hasObjectPhoto": true,
      "labelEvidence": "连珠纹扁茎剑\n格剑\n时代：春秋\n来源：征集\n收藏单位：中国青铜器博物院\n器博物院\nSword with beaded pattern and fat hilt.\nhilted and guard\nSpring and Autumn period\nCollectedfrom public\nents Factory\nCollection ofBaoji Bronze Ware Museum\nMuseum",
      "labelFacts": {
        "period": "春秋",
        "findspot": "征集",
        "collection": "中国青铜器博物院"
      },
      "inscriptionFocus": false,
      "sourceUnits": [
        {
          "start": 3659,
          "end": 3659,
          "id": "photo-group-3659"
        }
      ],
      "unitCount": 1,
      "sequenceRanges": [
        "3659"
      ],
      "sequenceLabel": "3659",
      "sequenceShortLabel": "3659",
      "research": {
        "name_origin": "“连珠纹扁茎剑”的名称由器类、纹饰、结构或器主线索组成。“连珠纹”指连续圆珠状单元组成的装饰带，扁茎是剑茎形制的补充说明；“扁茎”说明剑的握持部分横截面扁平，是剑体结构的一部分；名称指向兵器或车马器的功能部件，器形、受力面与装配位置比朝代标签更能说明其用途",
        "history": "“连珠纹扁茎剑”属于兵器或车马器。宝鸡周秦墓葬中，戈、剑、弩机、当卢、轭饰等往往与军事技术、车战和贵族身份同时出现，器物的功能不能与墓葬组合关系分开理解。",
        "form": "兵器要看刃部、援、内、胡、穿、茎、格等结构；车马器则要看连接、受力和装饰位置。照片中的局部图可以帮助判断它是实用部件、仪仗装饰还是兼具礼仪意义的象征物。",
        "decoration": "连珠纹扁茎剑的名称主要来自器形、用途或纹饰；如果出现“铭文释文”栏，铭文往往提供器主、纪年、工官或使用背景。没有稳定释读之前，本页只保留展签可确认的主题。",
        "inscription": "本组没有稳定可核对的铭文释文。器名、族名或纪年若出现在名称中，只表示展签识别线索，不等于已经完成逐字释读。",
        "significance": "兵器与车马器显示青铜技术并不只服务于祭祀礼器，也参与军事组织、交通和身份展演；它们是理解周秦社会结构的另一条入口。",
        "viewing": "先找出受力或使用部位，再看纹饰和铸造细节；剑看茎、格、首与刃，戈看援、内和穿，车马器看连接面与装饰面。",
        "evidence": "名称依据后置介绍牌与照片顺序校正；展签线索：时代为“春秋”，来源为“征集”，收藏单位为“中国青铜器博物院”。"
      }
