      "summary": "父丁鼎：按现场顺序归档；详情页按名称、形制、纹饰与铭文线索展开。",
      "status": "名称依据后置展签校正",
      "hasObjectPhoto": true,
      "labelEvidence": "父丁鼎\n时代：西周\n来源：1974年咸阳市武功县调拨\n收藏单位：中国青铜器博物院\nWine vessel (ding) of Fu Ding\nWesternZhou\nAllocated from Wugong County,Xianyang City in 1974\nCollection ofBaoji Bronze Ware Museum",
      "labelFacts": {
        "period": "西周",
        "findspot": "1974年咸阳市武功县调拨",
        "collection": "中国青铜器博物院"
      },
      "inscriptionFocus": false,
      "sourceUnits": [
        {
          "start": 3724,
          "end": 3726,
          "id": "photo-group-3724"
        }
      ],
      "unitCount": 1,
      "sequenceRanges": [
        "3724—3726"
      ],
      "sequenceLabel": "3724—3726",
      "sequenceShortLabel": "3724—3726",
      "research": {
        "name_origin": "“父丁鼎”的名称由器类、纹饰、结构或器主线索组成。鼎是三足或四足的炊煮、盛食与礼仪重器，器名最后的“鼎”说明器类；名称中的人名、族氏或作器者称谓，是器物专名的来源；它们可能与铭文中的自称、受命者或家族记忆有关",
        "history": "“父丁鼎”以鼎为器类，名称中的其余部分来自纹饰、器主、纪年或出土地线索。鼎在商周礼制中兼具炊煮、盛食与祭祀功能，宝鸡周原及其周边墓葬、窖藏所见鼎类，常被放在理解宗族、宴飨和政治秩序的核心位置。",
        "form": "鼎的基本识别点是腹、耳、足三部分；圆鼎与方鼎的口腹关系不同，分裆、附耳、带盖等变化又会改变使用方式与视觉重心。照片中可从足的数量与分布、耳的安装位置、腹部是否有扉棱来判断形制。",
        "decoration": "父丁鼎的纹饰线索以展签名称为准；若名称含“兽面、云雷、涡、乳钉、夔凤”等词，它们分别提示主体纹样，而不是可以直接替代完整铭文的释读。若展签出现“铭文释文”栏，本页只把器名与可核对的铭文主题分开呈现。",
        "inscription": "本组没有稳定可核对的铭文释文。器名、族名或纪年若出现在名称中，只表示展签识别线索，不等于已经完成逐字释读。",
        "significance": "鼎最值得看的不是单一的“厚重”，而是器形、纹饰和铭文怎样共同表达使用者的身份。带纪年或器主名的鼎，还能把礼器放回具体的王年、家族与事件之中。",
        "viewing": "先看足和耳确定鼎的类型，再沿口沿—腹部—圈足移动；局部图优先检查扉棱、主纹带、底部铸痕和可能的铭文位置。",
        "evidence": "名称依据后置介绍牌与照片顺序校正；展签线索：时代为“西周”，来源为“1974年咸阳市武功县调拨”，收藏单位为“中国青铜器博物院”。"
      }
