        "significance": "玉石和装饰类器物提供了不同于大型礼器的观察尺度：它们把个人身份、身体使用和审美偏好带入周秦物质文化。",
        "viewing": "先看整体轮廓与穿孔，再放大边缘、磨痕和纹样；对镜类器物应比较正面纹饰与背部钮、座或悬挂结构。",
