      "research": {
        "name_origin": "“父辛鼎”的名称由器类、纹饰、结构或器主线索组成。鼎是三足或四足的炊煮、盛食与礼仪重器，器名最后的“鼎”说明器类；名称中的人名、族氏或作器者称谓，是器物专名的来源；它们可能与铭文中的自称、受命者或家族记忆有关",
        "history": "“父辛鼎”以鼎为器类，名称中的其余部分来自纹饰、器主、纪年或出土地线索。鼎在商周礼制中兼具炊煮、盛食与祭祀功能，宝鸡周原及其周边墓葬、窖藏所见鼎类，常被放在理解宗族、宴飨和政治秩序的核心位置。",
        "form": "鼎的基本识别点是腹、耳、足三部分；圆鼎与方鼎的口腹关系不同，分裆、附耳、带盖等变化又会改变使用方式与视觉重心。照片中可从足的数量与分布、耳的安装位置、腹部是否有扉棱来判断形制。",
        "decoration": "父辛鼎的纹饰线索以展签名称为准；若名称含“兽面、云雷、涡、乳钉、夔凤”等词，它们分别提示主体纹样，而不是可以直接替代完整铭文的释读。若展签出现“铭文释文”栏，本页只把器名与可核对的铭文主题分开呈现。",
        "inscription": "现场介绍牌出现了“铭文释文/铭文大意”等栏位；本页将其作为铭文线索保留，未把 OCR 误读直接改写成定本。",
        "significance": "鼎最值得看的不是单一的“厚重”，而是器形、纹饰和铭文怎样共同表达使用者的身份。带纪年或器主名的鼎，还能把礼器放回具体的王年、家族与事件之中。",
        "viewing": "先看足和耳确定鼎的类型，再沿口沿—腹部—圈足移动；局部图优先检查扉棱、主纹带、底部铸痕和可能的铭文位置。",
        "evidence": "名称依据后置介绍牌与照片顺序校正；展签线索：时代为“现场展签未给出可稳定读取的时代栏”，来源为“现场展签未给出可稳定读取的出土信息”，收藏单位为“现场展签未给出可稳定读取的收藏单位”。"
      }
