      "research": {
        "name_origin": "“昔鸡簋”的名称由器类、纹饰、结构或器主线索组成。簋是盛放黍稷等熟食的食器，后来成为与鼎配合使用的礼器；名称中的人名、族氏或作器者称谓，是器物专名的来源；它们可能与铭文中的自称、受命者或家族记忆有关",
        "history": "“昔鸡簋”属于簋类食器系统，名称中的纹饰、耳数或器主标识来自展签。簋与鼎常以组合方式出现，观察它时应同时想到它在祭祀、宴飨和墓葬随葬中的配套关系。",
        "form": "簋通常以圆腹、双耳和圈足为基本结构，带盖、方座、四耳或双环耳会改变器物的体量与礼仪等级感。照片要把耳、盖钮、腹部纹带和圈足看作一个整体，而不是只看正面图案。",
        "decoration": "昔鸡簋的纹饰名称说明了视觉重点；器主名或族名则可能与铭文有关，但仅凭现场照片不能把 OCR 片段当作完整释文。出现“铭文释文”的展签，优先回看局部照片与正式拓本。",
        "inscription": "现场介绍牌出现了“铭文释文/铭文大意”等栏位；本页将其作为铭文线索保留，未把 OCR 误读直接改写成定本。",
        "significance": "簋把“食器”与“礼器”两个层面叠在一起：它一方面有明确的容纳功能，另一方面通过成组配置、器主铭记和纹饰秩序进入周代礼制。",
        "viewing": "先看圈足和耳部确认器类，再看盖与腹部是否同铭、纹带是否连续；成组照片合并后，可用缩略图对比不同角度的同一器物。",
        "evidence": "名称依据后置介绍牌与照片顺序校正；展签线索：时代为“现场展签未给出可稳定读取的时代栏”，来源为“现场展签未给出可稳定读取的出土信息”，收藏单位为“现场展签未给出可稳定读取的收藏单位”。"
      }
